#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""WOOD TABLES — бот и сайт в одном файле для Render.

Обязательные переменные: BOT_TOKEN, OWNER_TELEGRAM_ID,
TURSO_DATABASE_URL и TURSO_AUTH_TOKEN. URL Render определяется автоматически.
"""
import base64
import gzip
import json
import os
from pathlib import Path
import re
import shutil
import signal
import subprocess
import sys
import tempfile
import threading
import time
from urllib import error, parse, request

_SERVER = r'''import http from 'node:http';
import {Readable} from 'node:stream';
import {createClient} from '@libsql/client';
import worker from './worker.mjs';

// Адаптер сохраняет атомарность пакетов, от которой зависят игровые ставки и кошелёк.
const client = createClient({
  url: process.env.TURSO_DATABASE_URL,
  authToken: process.env.TURSO_AUTH_TOKEN,
  intMode: 'number',
});
function convert(result) {
  const results = result.rows.map(row => Object.fromEntries(result.columns.map(name => [name, row[name]])));
  return {success: true, results, meta: {changes: Number(result.rowsAffected || 0)}};
}
class Statement {
  constructor(sql, args = []) { this.sql = sql; this.args = args; }
  bind(...args) { return new Statement(this.sql, args); }
  async run() { return convert(await client.execute({sql: this.sql, args: this.args})); }
  async all() { return this.run(); }
  async first(column) {
    const row = (await this.all()).results[0] ?? null;
    return column && row ? (row[column] ?? null) : row;
  }
}
const DB = {
  prepare(sql) { return new Statement(sql); },
  async batch(stmts) {
    const result = await client.batch(stmts.map(s => ({sql: s.sql, args: s.args})), 'write');
    return result.map(convert);
  },
};
const env = {DB, BOT_TOKEN: process.env.BOT_TOKEN, OWNER_TELEGRAM_ID: process.env.OWNER_TELEGRAM_ID};
const ignoredHeaders = new Set(['host', 'connection', 'transfer-encoding', 'keep-alive', 'upgrade', 'proxy-connection']);

const server = http.createServer(async (req, res) => {
  try {
    const parsed = new URL(req.url || '/', 'http://localhost');
    const url = new URL('http://localhost');
    url.pathname = parsed.pathname;
    url.search = parsed.search;
    const headers = new Headers();
    for (const [name, value] of Object.entries(req.headers)) {
      if (value !== undefined && !ignoredHeaders.has(name.toLowerCase())) {
        if (Array.isArray(value)) for (const item of value) headers.append(name, item);
        else headers.set(name, value);
      }
    }
    const method = req.method || 'GET';
    const options = {method, headers};
    if (method !== 'GET' && method !== 'HEAD') { options.body = req; options.duplex = 'half'; }
    const result = await worker.fetch(new Request(url, options), env);
    res.statusCode = result.status;
    result.headers.forEach((value, name) => { if (!ignoredHeaders.has(name.toLowerCase())) res.setHeader(name, value); });
    if (!result.body || method === 'HEAD') { res.end(); return; }
    const stream = Readable.fromWeb(result.body);
    stream.on('error', () => res.destroy());
    res.on('close', () => stream.destroy());
    stream.pipe(res);
  } catch (error) {
    console.error('Ошибка обработки HTTP-запроса:', error?.message || 'неизвестная ошибка');
    if (!res.headersSent) { res.writeHead(500, {'content-type': 'application/json; charset=utf-8'}); res.end('{"error":"internal_error"}'); }
    else res.destroy();
  }
});
const port = Number(process.env.PORT || 10000);
if (!Number.isInteger(port) || port < 1 || port > 65535) throw new Error('Некорректный PORT');
server.listen(port, '0.0.0.0', () => console.log('WOOD TABLES: сайт запущен на порту ' + port));
worker.scheduled(null, env, {}).catch(() => {});
const cleanup = setInterval(() => worker.scheduled(null, env, {}).catch(() => {}), 60 * 1000);
cleanup.unref();
function stop() {
  clearInterval(cleanup);
  server.close(() => { try { client.close(); } finally { process.exit(0); } });
  setTimeout(() => process.exit(0), 3000).unref();
}
process.on('SIGTERM', stop);
process.on('SIGINT', stop);
'''
